long long factorial_iterative(int n) {
    if (n < 0) return -1;  // Error case

    long long result = 1;
    for (int i = 2; i <= n; i++) {
        // Check for overflow
        if (result > LLONG_MAX / i) {
            return -1;  // Overflow would occur
        }
