#define MAX_SIZE 5

typedef struct {
    int data[MAX_SIZE];
    int front;
    int rear;
    int size;
} CircularQueue;

void init_queue(CircularQueue *q) {
    q->front = 0;
    q->rear = -1;
    q->size = 0;
}

bool is_empty(const CircularQueue *q) {
    return q->size == 0;
}

bool is_full(const CircularQueue *q) {
    return q->size == MAX_SIZE;
}

bool enqueue(CircularQueue *q, int value) {
    if (is_full(q)) {
        return false;
    }
    q->rear = (q->rear + 1) % MAX_SIZE;
    q->data[q->rear] = value;
    q->size++;
    return true;
}

bool dequeue(CircularQueue *q, int *value) {
    if (is_empty(q)) {
        return false;
    }
    *value = q->data[q->front];
    q->front = (q->front + 1) % MAX_SIZE;
    q->size--;
    return true;
}

void display_queue(const CircularQueue *q) {
    if (is_empty(q)) {
        printf("Queue is empty\n");
        return;
    }

    printf("Queue: ");
    for (int i = 0; i < q->size; i++) {
        int index = (q->front + i) % MAX_SIZE;
        printf("%d ", q->data[index]);
    }
    printf("\n");
}

