// Cache-friendly transpose for larger matrices
void transpose_optimized(const int src[][3], int dest[][3], int n) {
    const int BLOCK_SIZE = 2;  // Small block for cache efficiency

    for (int i = 0; i < n; i += BLOCK_SIZE) {
        for (int j = 0; j < n; j += BLOCK_SIZE) {
            // Transpose block
            for (int bi = i; bi < i + BLOCK_SIZE && bi < n; bi++) {
                for (int bj = j; bj < j + BLOCK_SIZE && bj < n; bj++) {
                    dest[bj][bi] = src[bi][bj];
                }
            }
