int remove_duplicates(int arr[], int size) {
    if (size <= 1) {
        return size;
    }

    int unique_count = 1;  // First element is always unique

    for (int i = 1; i < size; i++) {
        int is_duplicate = 0;

        // Check if current element already exists in unique part
        for (int j = 0; j < unique_count; j++) {
            if (arr[i] == arr[j]) {
                is_duplicate = 1;
                break;
            }
        }

        // If not duplicate, add to unique part
        if (!is_duplicate) {
            arr[unique_count] = arr[i];
            unique_count++;
        }
    }

