int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

long long lcm(int a, int b) {
    if (a == 0 || b == 0) {
        return 0;
    }

    // Use formula: LCM(a,b) = (a * b) / GCD(a,b)
    // But calculate (a/gcd) * b to avoid overflow
    int gcd_value = gcd(a, b);
    return ((long long)a / gcd_value) * b;
}

long long lcm_multiple(int numbers[], int count) {
    if (count <= 0) return 0;
    if (count == 1) return numbers[0];

    long long result = numbers[0];
